--- 686/nes_native_sink165.c
+++ 687/nes_native_sink165.c
@@ -152,13 +152,16 @@
   bool adjacent=pair && count==3;
   /* BG complete is a single adjacent packet, never a map drain. */
   if(early==2 && !adjacent)return true;
-  if(!packet(s,(early==1||adjacent)?24:2,2,first*64,p->map+first*64,count*64))return false;
+  if(!packet(s,(early==1||adjacent)?24:2,2,first*64,p->map+first*64,count*64)){s->map_pair683=false;return false;}
   /* At most two exact192B map packets per producer query. Every
    * packet retains checked queue credit/CRC/STOP; gaps and short tails query.
    * BG-complete/row callbacks still return after their original one packet. */
   /* A ready, already owned tile retains producer priority. Only
    * an empty producer or completed receipt can lend its next query slot. */
-  pair=pairable && !adjacent && count==3 && !s->plan->bulk_pending;
+  /* Only the real checked-empty query lends its next slot. A
+   * receipt-only fast path cannot manufacture producer query credit. */
+  pair=pairable && count==3 && s->map_pair683;
+  s->map_pair683=false;
   if(early){s->map_next=(uint8_t)g;s->map_pair683=early==1 && count==3;break;}
  }
  return true;
--- 686/nes_plan_service200.c
+++ 687/nes_plan_service200.c
@@ -250,7 +250,13 @@
    if((mode==NES_MAP553 || mode==NES_ORDINARY553) && p->bulk_pending &&
       (uint16_t)(p->window->sent-p->window->retired)<=2)return true;
    if(!complete485(p))return false;
-  }else if(mode!=NES_FINAL553)return complete485(p);
+  }else if(mode!=NES_FINAL553){
+   /* No descriptor was returned. Complete any earlier owned receipt;
+    * a failed completion still fails the enclosing map send. This bit
+    * is consumed/cleared by map527, never a bank or display ACK. */
+   if(mode==NES_MAP553)p->sink->map_pair683=true;
+   return complete485(p);
+  }
   if(!wait485(p))return false;
  }
  return fail(p,6);
